const rowWith = (cells?:any[], id?:string):Row => { const c = cells ? cells.map(v=>v??"") : blank(); while(c.length<13)c.push(""); c[G.STATUS]=c[G.STATUS]||"Not reconciled"; return {id:id||crypto.randomUUID(),cells:c.slice(0,13)}; };
