const manualWith = (cells?:any[], id?:string):ManualRow => { let c:any[]; if(!cells)c=Array(M.REMARK+1).fill(""); else {const old=cells.map(v=>v??""); if(old.length>=M.REMARK+1)c=old; else if(old.length===14)c=[...old.slice(0,11),"","","",old[11],old[12],old[13]]; else if(old.length===13)c=[...old.slice(0,6),"",...old.slice(6,10),"","","",old[10],old[11],old[12]]; else c=old;} while(c.length<M.REMARK+1)c.push(""); return {id:id||crypto.randomUUID(),cells:c.slice(0,M.REMARK+1)}; };
