const pad2=(v:any)=>String(v).padStart(2,"0");
const isoDate=(y:any,m:any,d:any)=>`${String(y).padStart(4,"0")}-${pad2(m)}-${pad2(d)}`;
const dateKeys=(v:any):string[]=>{ if(v instanceof Date&&!Number.isNaN(v.getTime()))return[isoDate(v.getFullYear(),v.getMonth()+1,v.getDate())]; if(typeof v==="number"&&Number.isFinite(v)&&v>0){const p=XLSX.SSF.parse_date_code(v);return p?[isoDate(p.y,p.m,p.d)]:[];} const raw=text(v);if(!raw)return[];const iso=raw.match(/^(\d{4})[-/](\d{1,2})[-/](\d{1,2})/);if(iso)return[isoDate(iso[1],iso[2],iso[3])];const dmy=raw.match(/^(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})/);if(!dmy)return[];const a=Number(dmy[1]),b=Number(dmy[2]),y=dmy[3];if(a>12)return[isoDate(y,b,a)];if(b>12)return[isoDate(y,a,b)];return[isoDate(y,b,a),isoDate(y,a,b)]; };
