function parseSheet(file:File){return file.name.toLowerCase().endsWith(".csv")?file.text().then(t=>XLSX.utils.sheet_to_json<any[]>(XLSX.read(t,{type:"string"}).Sheets[XLSX.read(t,{type:"string"}).SheetNames[0]],{header:1,defval:""}) as any[][]):file.arrayBuffer().then(b=>{const wb=XLSX.read(b,{type:"array",cellDates:true});const n=wb.SheetNames.find(x=>x.toLowerCase().includes("sticker"))||wb.SheetNames[0];return XLSX.utils.sheet_to_json<any[]>(wb.Sheets[n],{header:1,defval:""}) as any[][]})}
