function chunkItems<T>(items:T[]){return Array.from({length:Math.ceil(items.length/FIREBASE_CHUNK_SIZE)},(_,i)=>items.slice(i*FIREBASE_CHUNK_SIZE,(i+1)*FIREBASE_CHUNK_SIZE))}

